/**
 * Convert language name (e.g. 'Russian', 'Spanish', 'Turkish') to lang code key.
 * Used by gemini-handler to pick correct translation.
 * Accepts both English language names and ISO codes.
 */
export function languageNameToCode(lang: string | undefined): LangCode {
  const map: Record<string, LangCode> = {
    // English names
    'English': 'en',
    'Russian': 'ru',
    'German': 'de',
    'Ukrainian': 'uk',
    'Spanish': 'es',
    'French': 'fr',
    'Italian': 'it',
    'Turkish': 'tr',
    // ISO codes
    'en': 'en',
    'ru': 'ru',
    'de': 'de',
    'uk': 'uk',
    'es': 'es',
    'fr': 'fr',
    'it': 'it',
    'tr': 'tr',
  };
  return map[lang || 'English'] || 'en';
}

/**
 * Look up an ingredient by INCI name.
 * Case-insensitive, trims whitespace.
 */
export function lookupIngredient(name: string): IngredientEntry | undefined {
  if (!name) return undefined;
  const key = name.trim().toLowerCase();
  return INGREDIENTS_DB[key];
}

/**
 * Get description in the requested language, falling back to English.
 */
export function getDescription(entry: IngredientEntry, lang: LangCode = 'en'): string {
  return entry.description[lang] || entry.description.en;
}
